pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    rolls: Vec<u16>,
    current_frame: u8,
    current_frame_rolls: u8,
    pins_on_lane: u16,
    game_over: bool,
}

impl BowlingGame {
    pub fn new() -> Self {
        BowlingGame {
            rolls: Vec::new(),
            current_frame: 0,
            current_frame_rolls: 0,
            pins_on_lane: 10,
            game_over: false,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if self.game_over {
            return Err(Error::GameComplete);
        }
        if pins > self.pins_on_lane {
            return Err(Error::NotEnoughPinsLeft);
        }

        self.rolls.push(pins);
        self.pins_on_lane -= pins;
        self.current_frame_rolls += 1;

        if self.current_frame < 9 {
            if pins == 10 || self.current_frame_rolls == 2 {
                self.current_frame += 1;
                self.current_frame_rolls = 0;
                self.pins_on_lane = 10;
            }
        } else {
            self.advance_tenth_frame(pins);
        }

        Ok(())
    }

    fn advance_tenth_frame(&mut self, pins: u16) {
        let n = self.rolls.len();
        let frame_start = n - self.current_frame_rolls as usize;
        let frame_rolls = &self.rolls[frame_start..];

        match self.current_frame_rolls {
            1 => {
                if pins == 10 {
                    self.pins_on_lane = 10;
                }
            }
            2 => {
                let first = frame_rolls[0];
                if first == 10 {
                    if pins == 10 {
                        self.pins_on_lane = 10;
                    }
                } else if first + pins == 10 {
                    self.pins_on_lane = 10;
                } else {
                    self.game_over = true;
                }
            }
            _ => {
                self.game_over = true;
            }
        }
    }

    pub fn score(&self) -> Option<u16> {
        if !self.game_over {
            return None;
        }

        let mut score = 0u16;
        let mut idx = 0usize;
        for _ in 0..10 {
            if self.rolls[idx] == 10 {
                score += 10 + self.rolls[idx + 1] + self.rolls[idx + 2];
                idx += 1;
            } else if self.rolls[idx] + self.rolls[idx + 1] == 10 {
                score += 10 + self.rolls[idx + 2];
                idx += 2;
            } else {
                score += self.rolls[idx] + self.rolls[idx + 1];
                idx += 2;
            }
        }
        Some(score)
    }
}
"}

